#!/usr/bin/env node
'use strict';
/**
 * check-ios-config — verify the generated Xcode project still matches ios-config/.
 *
 * mobile/ios/ is gitignored and generated by `cap add ios`, so it drifts silently
 * from mobile/ios-config/App/App/Info.plist. When it does, Xcode archives against
 * whatever the project happens to hold — which is how a build went to the wrong
 * App Store Connect record (co.za.svcapital.investor, 1.0.0/1) and was rejected
 * against an existing build 19.
 *
 * Xcode rejects a bad bundle id or build number only at upload, after the archive
 * is built and signed. This runs the same comparison in a second, beforehand.
 *
 * Usage:
 *   node scripts/check-ios-config.js          exit 1 on mismatch
 *   node scripts/check-ios-config.js --warn   always exit 0, print loudly
 */

const fs   = require('fs');
const path = require('path');

const WARN_ONLY = process.argv.includes('--warn');
const MOBILE    = path.resolve(__dirname, '..');
const TEMPLATE  = path.join(MOBILE, 'ios-config', 'App', 'App', 'Info.plist');
const PROJECT   = path.join(MOBILE, 'ios', 'App', 'App', 'Info.plist');
const PBXPROJ   = path.join(MOBILE, 'ios', 'App', 'App.xcodeproj', 'project.pbxproj');
const PRIVACY   = path.join(MOBILE, 'ios', 'App', 'App', 'PrivacyInfo.xcprivacy');
const CAPCONFIG = path.join(MOBILE, 'capacitor.config.json');

/* Minimal reader for a top-level <key>X</key><string>Y</string> pair. Deliberately
   not a general plist parser — it only needs the handful of identity keys below,
   and keeping it dependency-free means the check runs anywhere `npm run` does. */
function plistString(text, key) {
  const re = new RegExp(`<key>${key}</key>\\s*<string>([^<]*)</string>`);
  const m  = text.match(re);
  return m ? m[1].trim() : null;
}

/* Xcode commonly stores identity in build settings and leaves the plist holding
   a $(VAR) placeholder, so an unresolved value must be looked up in the pbxproj
   rather than compared literally. Takes the first value found; a project with
   per-configuration overrides is reported as ambiguous rather than guessed at. */
function resolveSetting(pbx, name) {
  if (!pbx) return { value: null, ambiguous: false };
  const all = [...pbx.matchAll(new RegExp(`${name}\\s*=\\s*"?([^;"\\n]+)"?\\s*;`, 'g'))]
    .map(m => m[1].trim())
    .filter(Boolean);
  const uniq = [...new Set(all)];
  return { value: uniq[0] || null, ambiguous: uniq.length > 1, all: uniq };
}

/* Map a build setting to its value per build configuration.
   In a pbxproj each configuration is an XCBuildConfiguration block holding a
   buildSettings dict followed by `name = Debug;` / `name = Release;`. Splitting on
   the isa marker yields one chunk per configuration containing both, which avoids
   brace-matching the nested dict.

   Naming the configuration matters: **Archive uses Release**, so when the
   identifier differs per configuration that is the one that decides where a build
   is delivered. Reporting only "they differ" leaves you guessing which to fix. */
function settingByConfig(pbx, name) {
  if (!pbx) return [];
  const out = [];
  const chunks = pbx.split('isa = XCBuildConfiguration;').slice(1);
  for (const c of chunks) {
    const v = c.match(new RegExp(`${name}\\s*=\\s*"?([^;"\\n]+)"?\\s*;`));
    const n = c.match(/\bname\s*=\s*"?([^;"\n]+)"?\s*;/);
    if (v) out.push({ config: n ? n[1].trim() : '(unnamed)', value: v[1].trim() });
  }
  return out;
}

function deref(raw, pbx) {
  if (!raw) return { value: raw, via: null, ambiguous: false };
  const m = raw.match(/^\$\((.+)\)$/);
  if (!m) return { value: raw, via: null, ambiguous: false };
  const r = resolveSetting(pbx, m[1]);
  return { value: r.value, via: m[1], ambiguous: r.ambiguous, all: r.all };
}

const problems = [];
const notes    = [];

function main() {
  if (!fs.existsSync(TEMPLATE)) {
    console.error(`[check:ios] template missing: ${path.relative(MOBILE, TEMPLATE)}`);
    return 1;
  }
  if (!fs.existsSync(PROJECT)) {
    console.log('[check:ios] mobile/ios/ not generated yet — nothing to check.');
    console.log('[check:ios] run `npm run add:ios`, then copy ios-config/ in (see README).');
    return 0;
  }

  const tpl = fs.readFileSync(TEMPLATE, 'utf8');
  const prj = fs.readFileSync(PROJECT, 'utf8');
  const pbx = fs.existsSync(PBXPROJ) ? fs.readFileSync(PBXPROJ, 'utf8') : null;
  if (!pbx) notes.push('project.pbxproj not found — $(VAR) values could not be resolved');

  const want = {
    id:      plistString(tpl, 'CFBundleIdentifier'),
    version: plistString(tpl, 'CFBundleShortVersionString'),
    build:   plistString(tpl, 'CFBundleVersion'),
  };
  const got = {
    id:      deref(plistString(prj, 'CFBundleIdentifier'), pbx),
    version: deref(plistString(prj, 'CFBundleShortVersionString'), pbx),
    build:   deref(plistString(prj, 'CFBundleVersion'), pbx),
  };

  // Bundle identifier — the one that sends a build to the wrong ASC record.
  if (got.id.ambiguous) {
    problems.push(`bundle id differs between build configurations: ${got.id.all.join(', ')}`);
  } else if (got.id.value !== want.id) {
    problems.push(`bundle id is "${got.id.value || '(unset)'}" — expected "${want.id}"`);
  }

  // Marketing version — build numbers must increase within one of these.
  if (got.version.value !== want.version) {
    problems.push(`version is "${got.version.value || '(unset)'}" — expected "${want.version}"`);
  }

  // Build number must be at least the template's; higher is fine and expected
  // once you have uploaded past it.
  const gotBuild  = parseInt(got.build.value, 10);
  const wantBuild = parseInt(want.build, 10);
  if (!Number.isFinite(gotBuild)) {
    problems.push(`build number is "${got.build.value || '(unset)'}" — expected a number >= ${want.build}`);
  } else if (gotBuild < wantBuild) {
    problems.push(`build number is ${gotBuild} — must be at least ${wantBuild} (App Store Connect rejects a repeat)`);
  } else if (gotBuild > wantBuild) {
    notes.push(`build ${gotBuild} is ahead of the template's ${wantBuild} — fine, but consider updating ios-config`);
  }

  /* PRODUCT_BUNDLE_IDENTIFIER is checked independently of the plist. Xcode uses it
     to pick the signing certificate and provisioning profile, so it decides which
     App Store Connect record a build is actually delivered to. When Info.plist
     carries a literal identifier the plist check above never consults the pbxproj,
     which would let a project pass with a correct plist and a build still signed
     against the wrong app. */
  const pbid    = resolveSetting(pbx, 'PRODUCT_BUNDLE_IDENTIFIER');
  const perCfg  = settingByConfig(pbx, 'PRODUCT_BUNDLE_IDENTIFIER');
  if (pbx) {
    if (pbid.ambiguous) {
      const detail = perCfg.length
        ? perCfg.map(c => `${c.config}="${c.value}"`).join(', ')
        : pbid.all.join(', ');
      problems.push(`PRODUCT_BUNDLE_IDENTIFIER differs between build configurations: ${detail}`);
      const bad = perCfg.filter(c => c.value !== want.id);
      for (const c of bad) {
        const isRelease = /release/i.test(c.config);
        problems.push(
          `  → ${c.config} is "${c.value}", must be "${want.id}"` +
          (isRelease ? '  ** Archive uses this configuration — it is what sent the build to the wrong app **' : '')
        );
      }
    } else if (!pbid.value) {
      notes.push('PRODUCT_BUNDLE_IDENTIFIER not found in project.pbxproj');
    } else if (pbid.value !== want.id) {
      problems.push(`PRODUCT_BUNDLE_IDENTIFIER is "${pbid.value}" — expected "${want.id}" (this is what signing and delivery use)`);
    }
  }

  // capacitor.config.json is the other place the identifier is declared.
  if (fs.existsSync(CAPCONFIG)) {
    try {
      const capId = JSON.parse(fs.readFileSync(CAPCONFIG, 'utf8')).appId;
      if (capId && capId !== want.id) {
        problems.push(`capacitor.config.json appId "${capId}" disagrees with the template "${want.id}"`);
      }
    } catch (_) { notes.push('capacitor.config.json could not be parsed'); }
  }

  // Required for App Store submission since May 2024.
  if (!fs.existsSync(PRIVACY)) {
    problems.push('PrivacyInfo.xcprivacy is missing from ios/App/App/ — App Store submissions require it');
  }

  const w = s => String(s == null ? '(unset)' : s);
  console.log('[check:ios] Xcode project vs ios-config template');
  console.log(`             bundle id  ${w(got.id.value).padEnd(28)} expected ${w(want.id)}${got.id.via ? `   (via $(${got.id.via}))` : ''}`);
  console.log(`             version    ${w(got.version.value).padEnd(28)} expected ${w(want.version)}`);
  console.log(`             build      ${w(got.build.value).padEnd(28)} expected >= ${w(want.build)}`);
  if (pbx) console.log(`             signing id ${w(pbid.ambiguous ? pbid.all.join(' / ') : pbid.value).padEnd(28)} expected ${w(want.id)}   (PRODUCT_BUNDLE_IDENTIFIER)`);

  for (const n of notes) console.log(`[check:ios] note: ${n}`);

  if (!problems.length) {
    /* Deliberately not "safe to archive". This compares the project against the
       repo template and cannot see App Store Connect, so it passed a 4.0.9/8
       configuration that Apple then rejected outright: 4.0.9 was already released,
       which closes the train to every build number. Claiming safety for something
       only Apple can adjudicate is worse than saying nothing. */
    console.log('[check:ios] OK — project matches ios-config.');
    console.log('[check:ios] Not checked (App Store Connect only knows these):');
    console.log('[check:ios]   · a released version is a closed train and rejects any build (90186)');
    console.log('[check:ios]   · build numbers already used within this train (90062)');
    console.log('[check:ios] If either bites, bump the version in ios-config and re-copy.');
    return 0;
  }

  console.error('');
  for (const p of problems) console.error(`[check:ios] MISMATCH: ${p}`);
  console.error('');
  console.error('[check:ios] Fix in Xcode (target App):');
  console.error('[check:ios]   Signing & Capabilities → Bundle Identifier');
  console.error('[check:ios]   General → Version / Build');
  if (pbid.ambiguous) {
    console.error('[check:ios] Because the identifier differs per configuration, set it for ALL of them:');
    console.error('[check:ios]   Build Settings → search "Product Bundle Identifier"');
    console.error('[check:ios]   expand the row and set every configuration (Debug and Release)');
    console.error('[check:ios]   Signing & Capabilities edits only the selected configuration.');
  }
  console.error('[check:ios] Or copy the template in, from an up-to-date checkout:');
  /* Printed relative to the caller's cwd, not to mobile/. npm run works from any
     subdirectory because npm walks up to find package.json, so this hint was
     regularly shown to someone standing somewhere the relative path did not
     resolve from. Falls back to absolute when that is shorter or clearer. */
  const rel = p => {
    const r = path.relative(process.cwd(), p);
    return !r || r.startsWith('..') && r.length > p.length ? p : (r.startsWith('.') ? r : r);
  };
  console.error(`[check:ios]   cp "${rel(TEMPLATE)}" "${rel(path.dirname(PROJECT))}/"`);
  return 1;
}

const code = main();
process.exit(WARN_ONLY ? 0 : code);
